def logge_aufruf(func):
    """
    Decorator: gibt vor jedem Aufruf Funktionsname und Argumente aus.
    Eingabe: func - beliebige Funktion
    Rückgabe: umhüllte Funktion mit gleichem Rueckgabewert
    """
    def wrapper(*args, **kwargs):
        print("Aufruf von", func.__name__, "mit", args, kwargs)
        return func(*args, **kwargs)
    return wrapper


@logge_aufruf
def addiere(a, b):
    return a + b


@logge_aufruf
def begruesse(name, gruss="Hallo"):
    return gruss + ", " + name


print(addiere(3, 4))
print(begruesse("Ada", gruss="Moin"))

