import functools

def laut(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs).upper()
    return wrapper

def leise(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs).lower()
    return wrapper

@laut
def gruss_a(name):
    """Begruesst eine Person."""
    return "Hallo, " + name

@leise
def gruss_b(name):
    """Begruesst eine Person."""
    return "Hallo, " + name

print(gruss_a("Ada"))
print(gruss_b("Ada"))
print(gruss_a.__name__)
print(gruss_b.__name__)
print(gruss_a.__doc__)
print(gruss_b.__doc__)

def gross(func):
    def wrapper(text):
        func(text).upper()
    return wrapper()

@gross
def begruessung(name, gruss="Hallo"):
    return gruss + ", " + name

print(begruessung("Ada", gruss="Moin"))

exercises.solution:
**Die drei Fehler**

1. **Zeile 4** - `return wrapper()`: Der wrapper wird sofort (und ohne Argument) aufgerufen. Richtig ist `return wrapper` **ohne Klammern**.
2. **Zeile 3** - das `return` fehlt: `func(text).upper()` berechnet den Wert und wirft ihn weg, der wrapper liefert `None`.
3. **Zeile 2** - `def wrapper(text)`: Der wrapper verträgt keine keyword-Argumente. Richtig ist `def wrapper(*args, **kwargs)` mit Weitergabe `func(*args, **kwargs)`.

**Korrigierte Fassung**

```python
import functools

def gross(func):
    @functools.wraps(func)          # optional, erhält die Metadaten
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs).upper()
    return wrapper

@gross
def begruessung(name, gruss="Hallo"):
    return gruss + ", " + name

print(begruessung("Ada", gruss="Moin"))   # MOIN, ADA
```

