def wiederhole(n):
    """
    Decorator-Fabrik: erzeugt einen Decorator, der die dekorierte Funktion
    n-mal aufruft und die Ergebnisse als Liste zurückgibt.
    Eingabe: n - Anzahl der Wiederholungen
    Rückgabe: Decorator (Funktion, die eine Funktion auf eine Funktion abbildet)
    """
    def dekorator(func):
        def wrapper(*args, **kwargs):
            return list(map(lambda i: func(*args, **kwargs), range(n)))
        return wrapper
    return dekorator


@wiederhole(3)
def gruss(name):
    return "Hallo, " + name
